changeSet.sql:
UPDATE wallet_service.wallets
SET version = 0
WHERE version IS NULL;

CREATE INDEX idx_outbox_pending_retry
ON wallet_service.outbox(next_retry_at, created_at)
WHERE status = 'PENDING';

ALTER TABLE wallet_service.trade_settlements
    DROP CONSTRAINT IF EXISTS uk_trade_settlements_trade_id;
ALTER TABLE wallet_service.trade_settlements
    DROP CONSTRAINT IF EXISTS trade_settlements_pkey;
ALTER TABLE wallet_service.trade_settlements
    ADD CONSTRAINT trade_settlements_pkey PRIMARY KEY (trade_id);
ALTER TABLE wallet_service.trade_settlements
    DROP COLUMN IF EXISTS id;

CREATE INDEX idx_trade_settlements_pending_event
ON wallet_service.trade_settlements(next_retry_at, settled_at, trade_id)
WHERE event_status = 'PENDING';

CREATE INDEX idx_wallet_outbox_in_flight_timeout
ON wallet_service.outbox(updated_at)
WHERE status = 'IN_FLIGHT';

CREATE TABLE wallet_service.message_inbox ( message_type VARCHAR(40) NOT NULL, message_id UUID NOT NULL, payload TEXT NOT NULL, payload_hash VARCHAR(64) NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempt_count INTEGER NOT NULL DEFAULT 0, next_retry_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, claimed_by VARCHAR(80), claim_until TIMESTAMP, received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, applied_at TIMESTAMP, error_type VARCHAR(80), last_error TEXT, conflict_detected_at TIMESTAMP, conflicting_payload TEXT, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (message_type, message_id), CONSTRAINT ck_wallet_message_inbox_type CHECK (message_type IN ('ORDER_SUBMITTED', 'ORDER_CANCELLATION_RESULT')), CONSTRAINT ck_wallet_message_inbox_status CHECK (status IN ('PENDING', 'PENDING_PREREQUISITE', 'IN_PROGRESS', 'APPLIED', 'FAILED_RETRYABLE', 'FAILED_PERMANENT')), CONSTRAINT ck_wallet_message_inbox_attempt CHECK (attempt_count >= 0), CONSTRAINT ck_wallet_message_inbox_schema CHECK (schema_version > 0) );
CREATE INDEX idx_wallet_message_inbox_retry ON wallet_service.message_inbox(status, next_retry_at, updated_at) WHERE status IN ('PENDING', 'PENDING_PREREQUISITE', 'FAILED_RETRYABLE', 'IN_PROGRESS');
CREATE TABLE wallet_service.order_asset_release_publications ( cancellation_id UUID PRIMARY KEY, event_id UUID NOT NULL UNIQUE, order_id UUID NOT NULL UNIQUE, recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );

UPDATE wallet_service.message_inbox SET status = 'FAILED_PERMANENT', error_type = 'PERMANENT_ASSET_INVARIANT', last_error = COALESCE(last_error, 'Wallet prerequisite state retired: manual consistency review required'), claimed_by = NULL, claim_until = NULL, updated_at = CURRENT_TIMESTAMP WHERE status = 'PENDING_PREREQUISITE';
ALTER TABLE wallet_service.message_inbox DROP CONSTRAINT ck_wallet_message_inbox_status; ALTER TABLE wallet_service.message_inbox ADD CONSTRAINT ck_wallet_message_inbox_status CHECK (status IN ('PENDING', 'IN_PROGRESS', 'APPLIED', 'FAILED_RETRYABLE', 'FAILED_PERMANENT'));
DROP INDEX wallet_service.idx_wallet_message_inbox_retry; CREATE INDEX idx_wallet_message_inbox_retry ON wallet_service.message_inbox(status, next_retry_at, updated_at) WHERE status IN ('PENDING', 'FAILED_RETRYABLE', 'IN_PROGRESS');

ALTER TABLE wallet_service.message_inbox
    ALTER COLUMN message_id TYPE VARCHAR(80)
    USING message_id::text;

ALTER TABLE wallet_service.message_inbox
    DROP CONSTRAINT ck_wallet_message_inbox_type;
ALTER TABLE wallet_service.message_inbox
    ADD CONSTRAINT ck_wallet_message_inbox_type
    CHECK (message_type IN ('ORDER_SUBMITTED',
                            'ORDER_CANCELLATION_RESULT',
                            'TRADE_EXECUTED'));

ALTER TABLE wallet_service.trade_settlements
    ADD COLUMN event_payload_hash VARCHAR(64);
